<!doctype html><html lang="th"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="5"><meta name="referrer" content="no-referrer"><title><?= e($display['name']) ?></title><link rel="stylesheet" href="assets/css/rra.css"></head><body class="rra-display"><header><h1><?= e($display['camp_name']) ?></h1><p><?= e($display['name']) ?></p></header><?php if($display['mode']==='idle'): ?><div class="display-idle">พร้อมเรียนรู้ พร้อมแข่งขัน<br><strong>ROBOT ACADEMY</strong></div><?php elseif($display['mode']==='scores'): ?><h2>ตารางคะแนน</h2><table><thead><tr><th>อันดับ</th><th>ทีม</th><th>คะแนน</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['rank']) ?></td><td><?= e($r['name']) ?></td><td><?= e(ScoringService::decimal($r['total'])) ?></td></tr><?php endforeach ?></tbody></table><?php else: ?><h2>การแข่งขัน</h2><?php foreach($rows as $r): ?><article class="panel"><h2><?= e($r['name']) ?> · สนาม <?= e($r['field_id']) ?></h2><p><?= e($r['teams']??'') ?></p><small><?= $r['status']==='playing'?'กำลังแข่งขัน':'รอแข่งขัน' ?> · คิว <?= e($r['queue_no']) ?></small></article><?php endforeach ?><?php if(!$rows): ?><p>ยังไม่มีแมตช์รอแข่งขัน</p><?php endif ?><?php endif ?></body></html>
